namespace {
int checks=0;
const char* controls[]={"grid-bounds-x","grid-bounds-y","grid-bounds-width","grid-bounds-height","grid-columns","grid-rows","grid-column-gutter","grid-row-gutter"};
const char* fields[]={"grid.bounds.x","grid.bounds.y","grid.bounds.width","grid.bounds.height","grid.columns","grid.rows","grid.column_gutter","grid.row_gutter"};
const char* sources[]={"20\n+ 0.5","30\n+ 0.5","900\n+ 0.5","700\n+ 0.5","3\n+ 1","2\n+ 1","7\n+ 0.5","8\n+ 0.5"};
void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);++checks;}
void events(){QApplication::processEvents();QApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);QTest::qWait(15);}
template<class T>T* control(Window& w,const QString& name){for(auto* c:w.findChildren<T*>(name))if(c->isVisible())return c;throw std::runtime_error(("Missing control: "+name).toStdString());}
QString name(int field,const char* suffix){return QString(controls[field])+suffix;}
void reveal(QWidget* c){for(auto* p=c->parentWidget();p;p=p->parentWidget())if(auto* s=qobject_cast<QScrollArea*>(p))s->ensureWidgetVisible(c);events();check(c->isVisible(),"Exact production control visible");}
std::optional<Expression>& expression(Grid& g,int field){std::optional<Expression>* field_sources[]={&g.bounds_x_expression,&g.bounds_y_expression,&g.bounds_width_expression,&g.bounds_height_expression,&g.columns_expression,&g.rows_expression,&g.column_gutter_expression,&g.row_gutter_expression};return *field_sources[field];}
std::optional<Ref>& driver(Grid& g,int field){std::optional<Ref>* field_drivers[]={&g.bounds_x_driver,&g.bounds_y_driver,&g.bounds_width_driver,&g.bounds_height_driver,&g.columns_driver,&g.rows_driver,&g.column_gutter_driver,&g.row_gutter_driver};return *field_drivers[field];}
void valid(const Document& d){validate(d);check(decode(encode(d))==d,"Independent full Document native-valid BEFORE Window");}
Document fixture(int mode){
 const int field=mode/2;const bool linked=mode%2;auto d=empty_document("grid-expression-keys-"+std::to_string(mode),"composition","board");auto& comp=d.compositions.front();auto& b=comp.artboards.front();b.width=1200;b.height=900;
 b.layout=ArtboardLayout{Margin{10.123456789012345,20.234567890123456,30.345678901234567,40.456789012345678},Grid{"grid",{15.123456789012345,20.234567890123456,1000.1234567890123,800.23456789012345},3,2,7.345678901234567,8.456789012345678}};
 auto& g=*b.layout->grid;const double literals[]={g.bounds.x,g.bounds.y,g.bounds.width,g.bounds.height,3,2,g.column_gutter,g.row_gutter};const int sibling=(field+1)%8;expression(g,sibling)=Expression{QString::number(literals[sibling],'g',17).toStdString(),1};
 const double driven[]={25,30,950,700,4,3,7,8};Artboard driver_board{"driver","Driver",1500,0,driven[field],900};
 if(linked&&(field==4||field==5)){driver(g,field)=Ref{"driver-grid","",fields[field]};driver_board.layout=ArtboardLayout{{},Grid{"driver-grid",{0,0,driver_board.width,driver_board.height},field==4?4u:1u,field==5?3u:1u,0,0}};}
 else if(linked)driver(g,field)=Ref{"driver","","artboard.width"};comp.artboards.push_back(driver_board);
 Object o;o.id="sentinel";o.kind=Kind::path;Contour c;c.id="contour";Point p;p.id="point";p.x.literal=51.25;p.y.literal=-21.75;c.points={p};o.contours={c};d.objects.emplace(o.id,o);comp.roots={o.id};valid(d);return d;
}
QString wrapped(int field){return QString(sources[field]).split('\n').first()+QString(" + 0").repeated(24)+QString(sources[field]).split('\n')[1];}
Document wanted(const Document& initial,int field){auto d=initial;auto& g=*d.compositions.front().artboards.front().layout->grid;driver(g,field).reset();expression(g,field)=Expression{wrapped(field).toStdString(),1};valid(d);return d;}
std::vector<Command> command(int field,bool replace){const Ref ref{"grid","",fields[field]};const Expression e{wrapped(field).toStdString(),1};switch(field){case 0:return {GridBoundsXCommand{SetGridBoundsXExpression{ref,e,replace}}};case 1:return {GridBoundsYCommand{SetGridBoundsYExpression{ref,e,replace}}};case 2:return {GridBoundsWidthCommand{SetGridBoundsWidthExpression{ref,e,replace}}};case 3:return {GridBoundsHeightCommand{SetGridBoundsHeightExpression{ref,e,replace}}};case 4:return {GridColumnsCommand{SetGridColumnsExpression{ref,e,replace}}};case 5:return {GridRowsCommand{SetGridRowsExpression{ref,e,replace}}};case 6:return {GridColumnGutterCommand{SetGridColumnGutterExpression{ref,e,replace}}};default:return {GridRowGutterCommand{SetGridRowGutterExpression{ref,e,replace}}};}}
void same(const Session& a,const Session& b){if(!(a.document()==b.document()&&a.history()==b.history()&&a.revision()==b.revision()&&a.gesture_active()==b.gesture_active()&&a.gesture_generation()==b.gesture_generation()))std::cerr<<"Snapshot doc="<<(a.document()==b.document())<<" history="<<(a.history()==b.history())<<" rev="<<a.revision()<<"/"<<b.revision()<<" active="<<a.gesture_active()<<"/"<<b.gesture_active()<<" gen="<<a.gesture_generation()<<"/"<<b.gesture_generation()<<"\n";check(a.document()==b.document()&&encode(a.document())==encode(b.document())&&a.preview_document()==b.preview_document()&&a.history()==b.history()&&a.revision()==b.revision()&&a.gesture_active()==b.gesture_active()&&a.gesture_generation()==b.gesture_generation(),"Full canonical Session equals independent pre-Window expectation");}
void write(const QString& path,const Document& d){QFile f(path);const auto bytes=encode(d);check(f.open(QIODevice::WriteOnly|QIODevice::NewOnly)&&f.write(bytes.data(),bytes.size())==static_cast<qint64>(bytes.size()),"Independent native oracle retained once");}
QByteArray read(const QString& path){QFile f(path);check(f.open(QIODevice::ReadOnly),"Owned native bytes readable");return f.readAll();}
QString prefix(const QString& root,int mode){return root+"/mode-"+QString::number(mode);}
void open(Window& w,const Document& d){w.host.session=Session(d);w.host.edited();w.canvas->set_active_artboard("composition","board",false);w.resize(1400,1000);w.show();w.activateWindow();events();auto* dock=w.findChild<QDockWidget*>("properties");check(dock,"Properties exists");dock->show();dock->raise();events();auto* edit=control<QPushButton>(w,"artboard-edit");reveal(edit);edit->click();events();}
void draft(Window& w,int field){auto* editor=control<QPlainTextEdit>(w,name(field,"-expression"));reveal(editor);editor->setFocus();QTest::keyClick(editor,Qt::Key_A,Qt::ControlModifier);const auto lines=QString(sources[field]).split('\n');QTest::keyClicks(editor,lines[0]);QTest::keyClick(editor,Qt::Key_Return);QTest::keyClicks(editor,lines[1]);events();check(editor->toPlainText()==sources[field],"Exact two-line source draft retained");}
void apply(Window& w,int field){auto* editor=control<QPlainTextEdit>(w,name(field,"-expression"));reveal(editor);editor->setFocus();QTest::keyClick(editor,Qt::Key_Return,Qt::ControlModifier);events();}
void reset(Window& w,const Document& d,const QString& key){w.host.session=Session(d);w.host.session_id+=key;w.host.edited();events();}
void cold(const QString& root,int mode){const auto d=wanted(fixture(mode),mode/2);Session expected(d);const auto path=prefix(root,mode);QSettings settings(root+"/settings.ini",QSettings::IniFormat);Window w(path+"-cold",std::make_unique<FolderLibrary>(settings),&settings);w.host.open(path+"-cold-input.nect");same(w.host.session,expected);w.host.save(path+"-resaved.nect");w.host.flush();same(w.host.session,expected);check(read(path+"-cold-input.nect")==read(path+"-expected.nect")&&read(path+"-resaved.nect")==read(path+"-expected.nect"),"Separate cold exact expression native bytes");QTest::qWait(120);}
void flow(const QString& root,int mode){
 const int field=mode/2;const auto initial=fixture(mode),intended=wanted(initial,field);Session before(initial),committed(initial);committed.apply(command(field,false),0);check(committed.document()==intended,"Independent full wrapped source command expectation BEFORE Window");const auto body=wrapped(field);
 const auto path=prefix(root,mode);write(path+"-initial.nect",initial);write(path+"-expected.nect",intended);QSettings settings(root+"/settings.ini",QSettings::IniFormat);Window w(path+"-recovery",std::make_unique<FolderLibrary>(settings),&settings);open(w,initial);same(w.host.session,before);
 auto* editor=control<QPlainTextEdit>(w,name(field,"-expression"));reveal(editor);editor->setFocus();QTest::keyClicks(editor,QString(sources[field]).split('\n').first());events();same(w.host.session,before);const auto one=editor->height();QTest::keyClick(editor,Qt::Key_A,Qt::ControlModifier);QTest::keyClicks(editor,body);events();same(w.host.session,before);check(editor->toPlainText()==body&&editor->document()->blockCount()==1,"Actual soft-wrapped source stays one logical block and unauthored");const auto visual=editor->document()->begin().layout()->lineCount();check(visual>1&&visual<=8,"Actual source wraps across multiple visible lines within bounded editor capacity");check(editor->parentWidget()->grab().save(path+"-wrapped.png"),"Actual wrapped source render retained");std::cout<<"WRAP field="<<field<<" logical="<<editor->document()->blockCount()<<" visual="<<visual<<" one="<<one<<" wrapped="<<editor->height()<<" scroll="<<editor->verticalScrollBar()->maximum()<<"\n";check(editor->height()>one&&editor->verticalScrollBar()->maximum()==0,"Soft-wrapped source expands to show all lines within capacity");
 w.host.save(path+"-draft-save.nect");w.host.flush();events();same(w.host.session,before);check(read(path+"-draft-save.nect")==read(path+"-initial.nect"),"Wrapped source draft remains excluded from native bytes");editor=control<QPlainTextEdit>(w,name(field,"-expression"));reveal(editor);std::cout<<"REFRESH field="<<field<<" body="<<(editor->toPlainText()==body)<<" logical="<<editor->document()->blockCount()<<" visual="<<editor->document()->begin().layout()->lineCount()<<" height="<<editor->height()<<" viewport="<<editor->viewport()->width()<<" scroll="<<editor->verticalScrollBar()->maximum()<<"\n";check(editor->parentWidget()->grab().save(path+"-refresh-diagnostic.png"),"Actual refresh diagnostic render retained");check(editor->toPlainText()==body&&editor->height()>one&&editor->verticalScrollBar()->maximum()==0,"Processed refresh restores exact soft-wrapped source and visible expansion");check(editor->parentWidget()->grab().save(path+"-after-refresh.png"),"Actual refreshed wrapped source render retained");
 draft(w,field);editor=control<QPlainTextEdit>(w,name(field,"-expression"));same(w.host.session,before);const auto explicit_two=editor->height();check(editor->document()->blockCount()==2&&explicit_two>one&&editor->verticalScrollBar()->maximum()==0,"Switch from soft wrapping to explicit two lines stays fully visible");QTest::keyClick(editor,Qt::Key_End,Qt::ControlModifier);QTest::keyClick(editor,Qt::Key_Return);QTest::keyClick(editor,Qt::Key_Return);events();same(w.host.session,before);check(editor->document()->blockCount()==4&&editor->height()>explicit_two&&editor->verticalScrollBar()->maximum()==0,"Mixed explicit four lines further expand without hidden text");check(editor->toPlainText()==QString(sources[field])+"\n\n","Mixed expansion keeps exact source text");check(editor->parentWidget()->grab().save(path+"-mixed-four-lines.png"),"Actual mixed four-line render retained");QTest::keyClick(editor,Qt::Key_A,Qt::ControlModifier);QTest::keyClicks(editor,body);events();same(w.host.session,before);check(editor->toPlainText()==body&&editor->document()->blockCount()==1&&editor->height()>one&&editor->verticalScrollBar()->maximum()==0,"Returning to soft-wrapped source retains full body and visible expansion");
 apply(w,field);same(w.host.session,committed);check(control<QPlainTextEdit>(w,name(field,"-expression"))->toPlainText()==body,"Canonical Apply commits exact wrapped source");w.host.save(path+"-saved.nect");w.host.flush();same(w.host.session,committed);check(QFile::copy(path+"-saved.nect",path+"-cold-input.nect"),"Actual saved wrapped source retained");QProcess child;child.start(QCoreApplication::applicationFilePath(),{"--cold",root,QString::number(mode)});check(child.waitForStarted(5000),"Owned cold starts");if(!child.waitForFinished(15000)){child.kill();child.waitForFinished();throw std::runtime_error("Owned cold deadline");}std::cout<<child.readAllStandardOutput().toStdString();std::cerr<<child.readAllStandardError().toStdString();check(child.exitStatus()==QProcess::NormalExit&&child.exitCode()==0,"Separate cold wrapped source byte acceptance passes");
 w.host.session.undo(w.host.session.revision());committed.undo(committed.revision());w.host.edited();events();same(w.host.session,committed);check(w.host.session.document()==initial,"One Undo restores full initial authored source/literals/IDs");w.host.session.redo(w.host.session.revision());committed.redo(committed.revision());w.host.edited();events();same(w.host.session,committed);
 reset(w,initial,"-cancel");editor=control<QPlainTextEdit>(w,name(field,"-expression"));reveal(editor);editor->setFocus();QTest::keyClicks(editor,body);events();QTest::keyClick(editor,Qt::Key_Escape);events();same(w.host.session,before);editor=control<QPlainTextEdit>(w,name(field,"-expression"));check(editor->toPlainText().isEmpty()&&editor->height()==one,"Cancel removes wrapped draft and restores compact empty field");
}

}
int main(int argc,char** argv){qputenv("QT_QPA_PLATFORM","windows");QApplication app(argc,argv);try{std::cout<<"Native platform="<<QGuiApplication::platformName().toStdString()<<" PID="<<QCoreApplication::applicationPid()<<"\n";if(argc==4&&std::string(argv[1])=="--cold")cold(QString::fromLocal8Bit(argv[2]),std::stoi(argv[3]));else{QTemporaryDir temporary;check(temporary.isValid(),"Owned scratch valid");const auto requested=qEnvironmentVariable("NECT_GRID_WRAPPED_SOURCE_ROOT"),root=requested.isEmpty()?temporary.path():requested;int failures=0;for(int mode=0;mode<16;mode+=2){try{flow(root,mode);std::cout<<"CASE PASS mode="<<mode<<"\n";}catch(const std::exception& e){++failures;std::cerr<<"CASE FAIL mode="<<mode<<" reason="<<e.what()<<" checks="<<checks<<"\n";}}if(failures)throw std::runtime_error("Independent expression key cases failed: "+std::to_string(failures));}std::cout<<"PASS Grid wrapped source "<<checks<<" checks\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL Grid wrapped source "<<e.what()<<" after "<<checks<<" checks\n";return 1;}}
